//! Dynamically loaded CUDA driver and NVDEC bindings plus preprocessing
//! kernels.
//!
//! Nothing is linked at build time and no CUDA toolkit is needed to build:
//! the driver (`nvcuda.dll` / `libcuda.so.1`) and NVDEC (`nvcuvid.dll` /
//! `libnvcuvid.so.1`) are loaded on first use, and the kernels ship as PTX
//! (generated by `cargo run -p xtask -- ptx`) that the driver JIT-compiles
//! for the installed GPU. Missing libraries surface as
//! [`camtensor_core::Error::Unavailable`].
//!
//! Main entry points:
//! * [`CudaDevice::get`] — cached device + primary context;
//! * [`CudaStream`], [`CudaEvent`] — asynchronous execution;
//! * [`DeviceBuffer`], [`PinnedHostBuffer`], [`BufferPool`] — memory;
//! * [`Preprocessor`] — fused resize / colour conversion / normalisation;
//! * [`nvdec`] — safe NVDEC parser and decoder wrappers.
//!
//! All objects use the device's primary context, shared with the CUDA
//! runtime, so pointers can be handed to TensorRT, PyTorch or ONNX Runtime.

#![deny(unsafe_op_in_unsafe_fn)]

pub mod device;
mod error;
pub mod memory;
pub mod module;
pub mod nvdec;
pub mod preprocess;
pub mod stream;
pub mod sys;

pub use device::{ContextGuard, CudaDevice, device_count};
pub use memory::{BufferPool, DeviceBuffer, PinnedHostBuffer};
pub use module::{Function, LaunchConfig, Module};
pub use preprocess::{Preprocessor, SampleItem, SourceImage};
pub use stream::{Copy2d, CudaEvent, CudaStream};

/// `true` when the CUDA driver loads and at least one device is present.
pub fn is_available() -> bool {
    device_count() > 0
}

/// CUDA driver version as `(major, minor)` (e.g. `(13, 0)`), if loadable.
pub fn driver_version() -> Option<(u32, u32)> {
    let api = sys::driver::api().ok()?;
    let mut v = 0;
    // SAFETY: valid out pointer; cuInit has succeeded.
    let r = unsafe { (api.cuDriverGetVersion)(&mut v) };
    (r == 0).then(|| ((v / 1000) as u32, ((v % 1000) / 10) as u32))
}
